mkdir -p /tmp/opencode/shots && cd /tmp/opencode && cat > shot.cjs <<'EOF'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 1000 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const errors=[]; page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: '/tmp/opencode/shots/home.jpg', type:'jpeg', quality: 70 });
  console.log('errors', errors);
  await browser.close();
})();
EOF
node shot.cjs

which magick convert montage; cd /tmp/opencode && cat > survey.cjs <<'EOF'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const views=['cultivate','paths','dao','combat','sect','techniques','expeditions','alchemy','inherit','forge','fate','ascension','codex'];
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 1000 } });
  await ctx.addInitScript(() => localStorage.setItem('stillwater-cultivator-v1', JSON.stringify({stage:18,qi:500000,stones:90000,hp:4000,maxHp:4000,sectRank:2,sectRep:600,sectTokens:200,herbs:{herb:30,root:30,flower:30,ore:30,essence:30,crystal:30,beastCore:10,voidDust:10,relic:10}})));
  const page = await ctx.newPage();
  const errors=[]; page.on('pageerror', e=>errors.push(e.message));
  await page.goto('http://localhost:3002/index.html', {waitUntil:'networkidle'});
  await page.waitForTimeout(600);
  for (const v of views) {
    await page.locator(`.nav-item[data-view="${v}"]`).click();
    await page.waitForTimeout(250);
    await page.screenshot({path:`/tmp/opencode/shots/v-${v}.jpg`, type:'jpeg', quality:60, fullPage:true});
  }
  console.log('errors', errors);
  await browser.close();
})();
EOF
node survey.cjs; ls -la shots

