```js
function defeatArenaRival(def) {
  const first = !(state.arena.defeated[def.id] > 0);
  const rank = state.arena.rank || 11;
  state.arena.defeated[def.id] = (state.arena.defeated[def.id] || 0) + 1;
  state.arena.wins = (state.arena.wins || 0) + 1;
  state.arena.lastWin = Date.now();
  if (first && rank === def.rank + 1) state.arena.rank = def.rank;
  state.arena.battle = null;
  const mult = first ? 1 : .35;
  const stones = Math.max(1, Math.round(def.stones * mult));
  const tokens = Math.max(1, Math.round(def.tokens * mult));
  const merit = Math.max(1, Math.round(def.merit * mult));
  state.stones += stones; state.sectTokens += tokens; addRep(merit);
  if (def.dao) state.dao[def.dao.id].xp = (state.dao[def.dao.id].xp || 0) + Math.round(def.dao.xp * mult * daoGainMult(def.dao.id));
  if (first && def.rank === 1) grantArtifact('laurel');
  dailyStep('duel'); missionStep('duel'); questStep('duel');
  state.stats.duels = (state.stats.duels || 0) + 1;
  state.hp = state.maxHp;
  notify(`Arena victory · ${def.name} defeated${first ? ` · rank ${state.arena.rank}` : ' · rematch'}.`, 'reward');
  save(); render();
  if (first) {
    if (def.rank === 1) openModal('冠', 'THE SEAT IS CLAIMED', 'Sect Champion', `Nangong Wan yields the champion's seat.<br><br>+${nfmt(stones)} spirit stones · +${tokens} tokens · +${merit} merit<br><b>Artifact claimed · Laurel of the Sect Champion</b><br><br>The stone ring will remember this day.`, '<button class="primary-btn" data-action="close-modal">Take the pedestal</button>');
    else fxBurst('rare', def.seal, `${def.name} defeated`, `You claim rank ${state.arena.rank} in the sect arena.`, rewardsText({ stones, tokens, merit }));
