  check('arena tab renders', await page.locator('.arena-hero').count() === 1);
  check('arena ladder 10 rivals', await page.locator('.arena-rival').count() === 10, String(await page.locator('.arena-rival').count()));
  check('next rival is rank 10', (await page.locator('.arena-rival.next .arena-rank-no').textContent()).trim() === '10');
  await page.screenshot({path:'/tmp/opencode/shots/arena1.jpg', type:'jpeg', quality:70, fullPage:true});
  // challenge first rival
  await page.locator('.arena-rival.next [data-action="challenge-rival"]').click(); await page.waitForTimeout(300);
  check('battle starts', await page.locator('.arena-battle').count() === 1);
  check('battle has 4+ actions', (await page.locator('.arena-battle .boss-actions .action-btn').count()) >= 4);
  await page.screenshot({path:'/tmp/opencode/shots/arena-battle.jpg', type:'jpeg', quality:70, fullPage:true});
  // attack until win or 25 turns
  let won=false;
  for (let i=0;i<30;i++) {
    if (await page.locator('.arena-battle').count() === 0) break;
    const body = page.locator('.arena-battle [data-action="arena-attack"][data-style="body"]');
    if (await body.count() && await body.isEnabled()) await body.click(); else break;
    await page.waitForTimeout(90);
    const state = await page.evaluate(()=>JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
    if ((state.arena?.defeated?.wenshuang || 0) > 0) { won=true; break; }
  }
  check('won first duel', won);
  const st = await page.evaluate(()=>JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
  check('arena rank advanced to 10', st.arena.rank === 10, 'rank='+st.arena.rank);
  check('arena wins recorded', st.arena.wins >= 1, 'wins='+st.arena.wins);
  check('reward stones gained', st.stones > 90000);
  check('arena achievement', !!st.achievements.arena1);
  check('notification created', st.notifications.some(n=>/Arena victory/.test(n.text)));
  await page.waitForTimeout(400);
  await page.screenshot({path:'/tmp/opencode/shots/arena2.jpg', type:'jpeg', quality:70, fullPage:true});
  // rematch
  const rematch = page.locator('.arena-rival.cleared [data-action="challenge-rival"]').first();
  check('rematch available', await rematch.count() > 0 && await rematch.isEnabled());
  check('no runtime errors', errors.length===0, errors.join(' | '));
  console.log(results.join('\n'));
  console.log(results.filter(r=>r.startsWith('FAIL')).length ? 'SOME FAILED' : 'ALL PASS');
  await browser.close();
})();
